contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        address oldOwner = c.owner();

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address finalOwner = c.owner();

        assert(reverted ? finalOwner == oldOwner : finalOwner == newOwner);
    }

    receive() external payable {}
}

