    }

    function run(address newOwner) public payable {
        address ownerBefore = c.owner();

        c.transferOwnership(newOwner);

        address ownerAfter = c.owner();

        assert(ownerAfter == newOwner);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        // Record who the current owner is; from a fresh deployment this is the test contract.
        address ownerBefore = c.owner();

        // Exercise the public entry point. It may revert if the caller is not the owner.
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule tying revert behavior to ownership and the resulting owner state.
        assert((reverted && ownerAfter == ownerBefore) || (!reverted && ownerAfter == newOwner));
    }

    receive() external payable {}
}

