contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        address ownerBefore = c.owner();
        require(msg.sender == ownerBefore);

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        assert(
            reverted
                ? ownerAfter == ownerBefore
                : ownerAfter == newOwner
        );
    }

    receive() external payable {}
}

